// A fixed-window rate limiter. Each instance owns its counters, its settings and its clock as instance
// properties, so two instances never share anything and one can be tested in isolation.

import { recordDenial } from "./audit-log.mjs";

export class RateLimiter {
	constructor() {
		this.counters = new Map();
		this.config = { windowMs: 60000, max: 5 };
		this.clock = () => Date.now();
	}

	configure(next) {
		this.config = { ...this.config, ...(next ?? {}) };
		return { ...this.config };
	}

	currentConfig() {
		return { ...this.config };
	}

	setClock(nextClock) {
		this.clock = typeof nextClock === "function" ? nextClock : () => Date.now();
	}

	reset() {
		this.counters = new Map();
	}

	windowFor(key, now) {
		const existing = this.counters.get(key);
		const window = existing && now < existing.resetAt ? existing : { hits: 0, resetAt: now + this.config.windowMs };
		this.counters.set(key, window);
		return window;
	}

	allow(key) {
		if (typeof key !== "string" || key === "") {
			throw new TypeError("a rate-limit key must be a non-empty string");
		}
		const now = this.clock();
		const window = this.windowFor(key, now);
		if (window.hits >= this.config.max) {
			recordDenial(key, now, this.config.max, this.config.windowMs);
			return { allowed: false, remaining: 0, resetAt: window.resetAt };
		}
		window.hits += 1;
		return { allowed: true, remaining: this.config.max - window.hits, resetAt: window.resetAt };
	}
}

// The module-level limiter every existing caller already uses. All state now lives in one named RateLimiter
// instance instead of module bindings.

import { RateLimiter } from "./rateLimiter.mjs";

const limiter = new RateLimiter();

export function allow(key) {
	return limiter.allow(key);
}

export function configure(next) {
	return limiter.configure(next);
}

export function currentConfig() {
	return limiter.currentConfig();
}

export function setClock(nextClock) {
	limiter.setClock(nextClock);
}

export function reset() {
	limiter.reset();
}

// Denial log. Takes the values it needs as arguments, so it never has to ask anything else what is true right
// now -- that is what made this module and the limiter unable to load independently.

const entries = [];

export function recordDenial(key, atMs, max, windowMs) {
	entries.push({ key, atMs, max, windowMs });
	return entries.length;
}

export function denials() {
	return entries.map((entry) => ({ ...entry }));
}

export function clearDenials() {
	entries.length = 0;
}
